/**
 * Classification corpus shared by unit tests (parser only) and integration tests (the same SQL
 * against real databases inside a read-only transaction). `safe` is whether the statement may run
 * under a read-only policy.
 */
export interface CorpusEntry {
  sql: string;
  kind: 'read' | 'write' | 'transaction' | 'session' | 'unknown';
  safe: boolean;
  /**
   * Only for integration: the database itself rejects it inside a read-only transaction. MySQL DDL
   * is not rejected there: it commits implicitly and runs (decision 0022).
   */
  databaseRejects?: boolean;
}

